from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option].SetFilter(
            -1000, 1000, timedelta(0), timedelta(days=730)
        )

        self.closes = RollingWindow[float](20)
        self.pending_entry = False
        self.no_entry_date = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A normal minute subscription and 5-minute consolidator produce
        # clock-aligned NY bars, including the first regular-session bar at 09:35.
        previous_fast = None
        previous_slow = None

        if self.closes.Count >= 20:
            previous_fast = sum(self.closes[i] for i in range(5)) / 5.0
            previous_slow = sum(self.closes[i] for i in range(20)) / 20.0

            current_fast = (bar.Close + sum(self.closes[i] for i in range(4))) / 5.0
            current_slow = (bar.Close + sum(self.closes[i] for i in range(19))) / 20.0

            bar_time = bar.EndTime.time()
            eligible_time = time(9, 45) <= bar_time <= time(14, 30)

            if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
                self.pending_entry = True

        # Only actual consolidated bars update the averages.
        self.closes.Add(bar.Close)

    def OnData(self, slice):
        today = self.Time.date()

        # Assignment/exercise is not a strategy entry.
        if self.Portfolio[self.spy].Quantity != 0:
            if self.equity_liquidation_order_id is None:
                quantity = -self.Portfolio[self.spy].Quantity
                ticket = self.MarketOrder(self.spy, quantity)
                self.equity_liquidation_order_id = ticket.OrderId
                self.Debug("Unexpected SPY assignment/exercise; liquidating equity.")

        if self.held_contract is not None:
            # Never intentionally carry a contract into its expiration date.
            if today >= self.held_expiry:
                self.no_entry_date = today
                self.SubmitExit("expiration processing")
            else:
                previous_trading_day = self.PreviousTradingDay(self.held_expiry)

                if today == previous_trading_day and self.Time.time() == time(15, 45):
                    self.SubmitExit("15:45 pre-expiration stop")
                else:
                    self.CheckProfitTarget(slice)

        if self.pending_entry:
            self.pending_entry = False

            if self.no_entry_date == today:
                self.Debug("Skipped selection: expiration-day entry block.")
                return

            if self.held_contract is not None or self.Portfolio.Invested:
                return

            if self.EntryOrderIsOpen():
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.option not in slice.OptionChains:
            self.Debug("Skipped selection: no SPY option chain in Slice.")
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped selection: no current SPY price in Slice.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid current SPY price.")
            return

        chain = slice.OptionChains[self.option]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not eligible_expiries:
            self.Debug("Skipped selection: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call at selected expiration.")
            return

        contract = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiry}, "
            f"strike {contract.Strike}"
        )

    def CheckProfitTarget(self, slice):
        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        contract = self.GetHeldContractFromSlice(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")

    def GetHeldContractFromSlice(self, slice):
        if self.held_contract is None:
            return None

        for chain in slice.OptionChains.Values:
            if self.held_contract in chain.Contracts:
                return chain.Contracts[self.held_contract]

        return None

    def SubmitExit(self, reason):
        if self.held_contract is None or self.ExitOrderIsOpen():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def PreviousTradingDay(self, expiration_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = datetime.combine(expiration_date - timedelta(days=1), time.min)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def EntryOrderIsOpen(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def ExitOrderIsOpen(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event):
        terminal_statuses = (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

        if order_event.OrderId == self.entry_order_id:
            if order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                )

            if order_event.Status in terminal_statuses:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                )
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None

            if order_event.Status in terminal_statuses:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_liquidation_order_id:
            if order_event.Status in terminal_statuses:
                self.equity_liquidation_order_id = None
