from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option_security.Symbol
        # Broad enough for the 1%-OTM strike and expirations beyond seven days.
        option_security.SetFilter(-100, 100, timedelta(0), timedelta(days=730))

        # 21 values are retained so both the current and preceding 20-bar SMAs
        # can be computed without using future data.
        self.closes = RollingWindow[float](21)
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.pending_entry_signal = False
        self.held_contract = None
        self.held_expiry = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.block_entries_on_date = None
        self.spy_cleanup_order_id = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.TimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        # With regular-hours minute SPY data, the first session bar is 09:30-09:35.
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(0, 5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(0, 20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        end_time = bar.EndTime.time()
        eligible_time = (
            end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30)
        )

        if (eligible_time and
                previous_fast <= previous_slow and
                current_fast > current_slow):
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        if self.HasOptionHolding():
            self.CheckProfitTarget(data)

        # A signal is evaluated only in the Slice immediately following the
        # completed five-minute consolidation event; it is never queued.
        if not self.pending_entry_signal:
            return

        self.pending_entry_signal = False

        if self.block_entries_on_date == self.Time.date():
            self.Debug("Skipped entry: expiration processing day.")
            return

        if self.HasOptionHolding() or self.EntryOrderIsOpen() or self.ExitOrderIsOpen():
            return

        self.TryEnterFromCurrentSlice(data)

    def TryEnterFromCurrentSlice(self, data):
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        chain = data.OptionChains.get(self.option_symbol, None)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at nearest valid expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_fill_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def CheckProfitTarget(self, data):
        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        quote = data.QuoteBars.get(self.held_contract, None)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("profit target")

    def TimeStop(self):
        if not self.HasOptionHolding() or self.held_expiry is None:
            return

        prior_trading_day = self.PreviousSpyTradingDay(self.held_expiry)
        if self.Time.date() == prior_trading_day:
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationProcessing(self):
        if not self.HasOptionHolding() or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.block_entries_on_date = self.Time.date()
            self.Debug("Expiration processing detected an open option; liquidating.")
            self.SubmitExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if self.spy_cleanup_order_id is None:
            quantity = -self.Portfolio[self.spy].Quantity
            ticket = self.MarketOrder(self.spy, quantity)
            self.spy_cleanup_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position; liquidating SPY.")

    def SubmitExit(self, reason):
        if not self.HasOptionHolding() or self.ExitOrderIsOpen():
            return

        # Cancel any other open order for the held option before submitting exit.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, reason)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def PreviousSpyTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def HasOptionHolding(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def EntryOrderIsOpen(self):
        if self.entry_order_id is None:
            return False
        return any(
            order.Id == self.entry_order_id
            for order in self.Transactions.GetOpenOrders()
        )

    def ExitOrderIsOpen(self):
        if self.exit_order_id is None:
            return False
        return any(
            order.Id == self.exit_order_id
            for order in self.Transactions.GetOpenOrders()
        )

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.entry_fill_price = orderEvent.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order did not fill.")
                self.entry_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol}.")
                self.exit_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if orderEvent.OrderId == self.spy_cleanup_order_id:
